  `idImportacoes` int DEFAULT NULL,
  `createdAt` datetime DEFAULT CURRENT_TIMESTAMP,
  `encerrado` varchar(1) DEFAULT 'N',
  PRIMARY KEY (`idnfpendencias`),
  KEY `nfUnidade_idx` (`idUnidade`),
